import{_ as l,l as o,o as e,c as s,v as r,p as n,x as i,d,i as p,S as h}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"模型检验直觉","description":"","frontmatter":{"title":"模型检验直觉","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/model-checking.md","filePath":"cs/model-checking.md","lastUpdated":1789023840000}'),c={name:"cs/model-checking.md"};function m(B,a,E,T,_,u){const t=o("Mermaid");return e(),s("div",null,[a[1]||(a[1]=r('<h1 id="模型检验直觉" tabindex="-1">模型检验直觉 <a class="header-anchor" href="#模型检验直觉" aria-label="Permalink to &quot;模型检验直觉&quot;">​</a></h1><div class="epigraph"><p>有限转移系统上，时序性质可算成标注或不动点迭代；对则给出路径证据，错则给反例路径。状态爆炸是边界，不是定义。</p><footer>—— 据 Clarke, Emerson and Sifakis；Clarke, Grumberg and Peled, Model Checking 整理</footer></div><p>上一课<a href="/cs/knaster-tarski-fixpoint">Knaster–Tarski</a> 给出 \\(\\mu\\) 可迭代。缺口是<strong>模型检验</strong>：模型 \\(M\\)（Kripke / 转移图）+ 性质 \\(\\varphi\\)，问 \\(M\\models\\varphi\\)。有限则算法；反例是调试接口。性质的逻辑 LTL/CTL 下一课，本课先钉流程与状态爆炸。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>状态：程序计数器 + 变量有限域。转移：语句一步。安全：坏态不可达——从初态 \\(\\mu\\) 后像，看交。活性：某事终发生——更要公平性与 \\(\\nu\\)。显式检验：存全体可达。符号：BDD / SAT 表示集合。有界模型检验：把 \\(k\\) 步路径编成 SAT，下一课 DPLL 吃它。</p><p>Hoare 要不变式；这里用穷尽（有限时）。无限整数、无限堆要抽象，否则非有限模型。</p><h3 id="不是测试覆盖" tabindex="-1">不是测试覆盖 <a class="header-anchor" href="#不是测试覆盖" aria-label="Permalink to &quot;不是测试覆盖&quot;">​</a></h3><p>覆盖率抽样本。模型检验相对给定有限模型是穷尽。模型若切掉中断或把 int 缩成 1 比特，穷尽的是切片，不是真机。</p><p><span class="marginnote">Clarke–Emerson、Queille–Sifakis 1980s，2007 图灵奖。CGP 教材。SPIN、NuSMV 是工具名，不是定义。状态爆炸：变量积。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画三状态互斥，检验「不会同在临界区」。可达集合迭代到不动点。错时吐路径。指出：线程积指数，对称、偏序约减是工程，点名。</p>',11)),(e(),n(h,null,{default:i(()=>[p(t,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PROG%5B%22%E6%9C%89%E9%99%90%E7%8A%B6%E6%80%81%E7%A8%8B%E5%BA%8F%22%5D%20--%3E%20TS%5B%22%E8%BD%AC%E7%A7%BB%E7%B3%BB%E7%BB%9F%22%5D%0A%20%20TS%20--%3E%20FIX%5B%22%CE%BC%2F%CE%BD%20%E8%BF%AD%E4%BB%A3%22%5D%0A%20%20FIX%20--%3E%20YES%5B%22%E6%88%90%E7%AB%8B%20%2F%20%E5%8F%8D%E4%BE%8B%E8%B7%AF%E5%BE%84%22%5D%0A"})]),fallback:i(()=>[...a[0]||(a[0]=[d(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>验证补层的自动支路：不写证明，写模型+性质。与证明助手对偶。可靠性：工具实现要可信；性质写错会「检验通过」而无意义。公平性（进程无限常被调度）必须声明，否则活性假失败。</p><p>符号 BDD：状态集当布尔函数。BMC：路径约束成 SAT，完成本课只到「会调用求解器」。偏序约减、对称、锥约减是对抗爆炸的工程。公平性约束（弱/强）改变路径集合，活性公式必须带上，否则「永不调度」当反例。工具可信性是另一层（证明助手可核）。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写 CTL 语义全文（下一课），不引入时间自动机。不把硬件时钟树当模型。后课默认：有限 \\(M\\) 上可自动判定许多时序性质，瓶颈是状态数。下一课 LTL / CTL。</p><p>穷尽的是给定有限模型，不是未切片的真机。反例路径是调试接口。状态积指数，故有符号方法与 SAT 有界展开。性质语言 LTL/CTL 下一课才选线性还是分支。</p><p>上一课留下的缺口在本课收口；「模型检验直觉」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>模型检验：有限转移系统 + 性质，不动点或 SAT。</li><li>错则反例路径；对则相对该模型穷尽。</li><li>状态爆炸与模型切片是边界。</li><li>后课先选 LTL 或 CTL，再谈具体算法。</li><li>出处：Clarke, Emerson, Sifakis；Clarke, Grumberg and Peled。</li></ul>',9))])}const C=l(c,[["render",m]]);export{f as __pageData,C as default};
